async def open_case(b,query='',data=None):
 c=await b.new_context(viewport={'width':1280,'height':1800});p=await c.new_page();
 if os.environ.get('INTAKE_PHONE'): await p.set_viewport_size({'width':390,'height':844})
 errors=[];p.on('pageerror',lambda e:errors.append(str(e)));await p.goto(BASE);await p.evaluate('d=>{localStorage.clear();localStorage.setItem("hiv-intake:user-a:biz-test",JSON.stringify(d));}',data or seed);await p.goto(BASE+'?'+query);return c,p,errors
async def upload(p,names):
 await p.locator('input[aria-label="Choose files"]').set_input_files([{'name':n,'mimeType':'application/pdf','buffer':b'TEST PDF'} for n in names])
